    static let cornFieldNightV1 = SmallCases.make(
        key: "story.cornFieldNight",
        category: .property,
        headlines: ["Pumpkin Patch Stripped of Forty Pumpkins at Night, Tire Marks Lead to Roadside Stand", "Trail Camera Catches Truck Backing Into the Rows"],
        law: "misdLarceny",
        spec: "Stole pumpkins valued at $260 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A farm's pumpkin patch was stripped of forty pumpkins overnight on {DATE}, just before a weekend sale. A trail camera showed a pickup backing into the rows at 2 a.m. Tire marks led to the road, and a deputy found {D}'s roadside stand two miles away selling pumpkins with sticky stem scars and a few with the farm's price stickers. {DL} says {D.he} bought the pumpkins from a farmer at a wholesale lot.",
        state: [E(.video, 3, "Trail Camera", "A pickup backs into the pumpkin rows."), E(.physical, 2, "Stand Pumpkins", "Pumpkins with the farm's price stickers."), E(.physical, 2, "Tire Marks", "Match {D}'s pickup tread."), E(.document, 1, "Farm Inventory", "Forty pumpkins missing.")],
        defense: [E(.statement, 1, "Wholesale Purchase", "{DL} says {D.he} bought them at a wholesale lot."), E(.document, 1, "Fuel Receipt", "A receipt placing {D} at a fuel station at 2:10 a.m.")],
        role: "Farmer",
        exam: [.direct("What did you find in your pumpkin patch on {DATE}?", "\"Forty pumpkins were stripped overnight, just before our weekend sale. My farm inventory shows forty missing, and I found the rows bare around seven.\""), .direct("What did your trail camera record?", "\"A pickup backing into the rows at 2 a.m. Tire marks led out to the road, and they match the tread on {D}'s pickup.\""), .direct("How did you find {DL}?", "\"A deputy found {D}'s roadside stand two miles away. It was selling pumpkins with sticky stem scars and a few of my farm's price stickers still on them.\""), .direct("How big is your pumpkin patch and what was planned for the weekend?", "\"About three acres. We were set to open for a weekend sale with families, hayrides, and a stand at the road. Forty pumpkins were the best ones for the front display.\""), .direct("What did you see on the trail camera?", "\"At 2 a.m. a pickup backed into the rows with its lights off. A person climbed out and loaded pumpkins by hand for about twenty minutes.\""), .direct("What did the deputy find at the stand?", "\"Pumpkins with sticky stem scars and a few with our orange price stickers still on them. The stand sat two miles down the road.\""), .cross("{DL} says {D.he} bought them at a wholesale lot, doesn't {D.he}?", "\"Wholesale pumpkins do exist. But mine carried my price stickers, which a wholesale lot would not put on.\""), .cross("A receipt puts {DL} at a fuel station at 2:10 a.m., doesn't it?", "\"I've heard of that receipt. I don't know where the station is, and I can't say how far it is from my field.\""), .cross("Did you see the driver on the camera?", "\"No. The camera shows a pickup. It doesn't show a face, and the picture is dark.\""), .cross("Could pumpkins from a wholesale lot carry your stickers?", "\"Wholesale lots sell pumpkins without a farm's retail stickers. Mine had our stickers, and I printed them myself.\""), .cross("Did you see anyone in the field that night?", "\"No. I was asleep. I only know what the camera caught and what I found at seven.\"")],
        theory: ("{D} took a farm's pumpkins and sold them at a stand.", "A seller who bought pumpkins wholesale."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} had no receipt for the pumpkins.", "{DL} rented the stand the week before and bought stock from a wholesale lot that week."),
        defendant: [.direct("Where did your pumpkins come from?", "\"I bought them from a farmer at a wholesale lot that week. I rented the stand to sell them, and I bought stock to fill it.\""), .direct("Where were you at 2 a.m.?", "\"At a fuel station. I have a receipt stamped 2:10 a.m. I was filling up for an early run to pick up stock.\""), .direct("Did you take pumpkins from {V}'s patch?", "\"No. I have never been in that field. I would not steal from a farm.\""), .direct("What did you do to get the stand started?", "\"I rented a space by the road a week earlier and bought stock at a wholesale lot that week. I paid cash to the farmer there.\""), .direct("How did you react when the deputy came?", "\"I told the deputy where I got the pumpkins and showed the fuel receipt. I did not know any had come from a farm's patch.\""), .direct("How did the pumpkins with price stickers end up at your stand?", "\"I bought a load from a wholesale lot and did not check the stickers. I wish I had peeled them or asked, and I have no receipt.\""), .cross("Some of your pumpkins had the farm's price stickers, didn't they?", "\"A few did. I didn't notice. I figured the farmer who sold them to me had used the stickers.\""), .cross("You have no receipt for buying the pumpkins, do you?", "\"No. It was cash at a lot. I know that is hard to prove.\""), .cross("The tire marks match your pickup, don't they?", "\"They said the tread matches. It's a very common tire, and plenty of pickups wear it.\""), .cross("A pickup backed into those rows with tire marks matching yours. Is your truck the only one with that tire?", "\"No. It is a very common tire, and plenty of trucks around here use it.\""), .cross("You have no receipt for the pumpkins. Why should the jury believe a cash story?", "\"It was a cash lot and I did not ask for a receipt. I know that leaves me with only my word and the fuel stamp.\"")],
        openings: ("Forty pumpkins vanished from a farm's patch the night before a weekend sale. A trail camera shows a pickup in the rows at 2 a.m., the tire marks match {D}'s pickup, and {D}'s roadside stand sold pumpkins with the farm's stickers. The State will show it all.", "The defense evidence includes a seller who bought pumpkins from a wholesale lot, a fuel receipt that puts {D} at a gas station at 2:10 a.m., and a camera with no face in it."),
        closings: ("Forty pumpkins gone, a pickup on camera, tire marks that match, and the farm's own price stickers on pumpkins at {D}'s stand. That is what a theft leaves behind.", "A common tire, a dark camera, and a fuel receipt at 2:10 a.m. The State has not proved {D} was in that field or knew the pumpkins were stolen."),
        timeline: [(-7, "{D} rents the stand."), (0, "2 a.m.: the pickup backs into the rows."), (0, "7 a.m.: the farmer finds the patch bare."), (1, "The trail camera is reviewed."), (2, "A deputy visits the stand.")],
        identified: "A trail camera.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let ladderTruckV1 = SmallCases.make(
        key: "story.ladderTruck",
        category: .property,
        headlines: ["Pressure Washer Taken From Contractor's Trailer at Job Site Over Lunch", "Text Message Asks 'Can I Borrow It?' an Hour After"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a contractor, valued at $310, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A contractor left a pressure washer in an unlocked trailer at a job site on {DATE} and went to lunch. A site camera showed {D}, a worker for another crew, wheel the washer to a car. An hour later {D} texted {V} asking whether {D.he} could 'borrow' it. {V} said no and called deputies. The pressure washer was worth $310. {DL} says {D.he} meant to borrow it and was going to return it.",
        state: [E(.video, 3, "Site Camera", "{D} wheels the washer to a car."), E(.digital, 2, "Text Message", "'Can I borrow it?' sent after it was gone."), E(.physical, 2, "Washer", "Recovered from {D}'s trunk."), E(.document, 1, "Purchase Receipt", "$310 purchase.")],
        defense: [E(.statement, 1, "Meant to Borrow", "{DL} says {D.he} meant to return it."), E(.statement, 1, "Open Trailer", "The trailer was unlocked.")],
        role: "Contractor",
        exam: [.direct("What did you leave in the trailer when you went to lunch?", "\"A pressure washer worth $310, in an unlocked trailer at our job site. I went to lunch and expected it to be there when I got back.\""), .direct("What did {D} do about it?", "\"An hour later {D} texted me asking whether {D.he} could 'borrow' it. By then it was already gone, and I told {D} no and called deputies.\""), .direct("What was the washer and why was it on site?", "\"A commercial pressure washer worth $310, kept in an unlocked trailer for our cleanup job that afternoon.\""), .direct("What did your site camera show at 12:15?", "\"{D}, who works for another crew, wheeled the washer out of the trailer and loaded it into a car. {D} drove off without telling anyone.\""), .direct("How did you learn who took it?", "\"About an hour later {D} texted me asking whether {D.he} could borrow it. The washer was already gone.\""), .direct("What did you do when you saw the empty spot where the washer had been?", "\"I checked the trailer lock, then my crew, and then I pulled up the camera feed. The footage showed the washer rolling to a car in daylight.\""), .cross("{D} says {D.he} meant to borrow it and return it, doesn't {D.he}?", "\"That is what {D} says. But the washer was already in a car when I got the text, so no one had said yes.\""), .cross("Was the trailer locked?", "\"No, it was unlocked. I should have locked it, and I will admit that. It still was not {D}'s to take.\""), .cross("Was the washer recovered?", "\"Yes. Deputies recovered it from the trunk of {D}'s car. It was not damaged.\""), .cross("Did {D} try to return it?", "\"{D} offered to. After I said no and called deputies, the washer was recovered from the trunk.\""), .cross("Was {D} hiding?", "\"No. {D} worked in the open in daylight on camera.\"")],
        theory: ("{D} took a pressure washer and asked afterwards.", "A worker who meant to borrow it."),
        allocution: "\"I knew it wasn't mine. I'll pay it back.\"",
        truths: ("{DL} asked to borrow it only after taking it.", "{DL} drove away before sending the text."),
        defendant: [.direct("Did you take the pressure washer?", "\"I took it to borrow it. I had a cleaning job that afternoon, and I planned to bring it back before the crew was done.\""), .direct("Why did you text the owner an hour later?", "\"I wanted to ask, and I knew I should have asked first. I sent the text when I realized I had not.\""), .direct("Where did you take the washer?", "\"To my car, and I drove off to start the job. I meant to return it that same day.\""), .direct("Why did you need a pressure washer that day?", "\"I had a driveway cleaning job at one o'clock and my own washer was broken. I saw this one sitting in the trailer.\""), .direct("What did you do after loading it?", "\"I drove to my job and started using it. It was in my trunk when deputies came.\""), .direct("When did you text the owner?", "\"About an hour after I left. I was nervous and wanted to ask, and I should have asked before taking it.\""), .cross("You took it and then asked, didn't you?", "\"Yes. I did it in the wrong order. I drove away before I sent the text, and That looks bad, I know.\""), .cross("Nobody told you that you could borrow the washer, did they?", "\"No. No one did. I assumed it would be fine, and that was a mistake.\""), .cross("It was in the trunk of your car when deputies found it. Why had you not returned it?", "\"I had not finished the job yet. I was going to bring it back, but deputies came first.\""), .cross("The owner was at lunch. Why not wait to ask in person?", "\"I was in a hurry and thought the owner would say yes. That was a bad call.\""), .cross("You asked to 'borrow' it after it was already in your car. Isn't that taking first?", "\"Yes. I did it in the wrong order and It looks bad, I know.\"")],
        openings: ("A contractor left a $310 pressure washer in an unlocked trailer at a job site. A site camera shows {D}, a worker for another crew, wheeling it to a car, and an hour later {D} texted to ask if {D.he} could 'borrow' it.", "The defense will present evidence that {D} meant only to borrow the washer for a cleaning job and return it that day, and that {D} told the owner within the hour."),
        closings: ("{D} took the washer, drove away, and only then asked to borrow it. The text came after the taking, and the washer was found in {D}'s trunk.", "{D} wheeled the washer out in the open, texted the owner within the hour, and meant to bring it back. That is carelessness about asking, not an intent to steal."),
        timeline: [(0, "12 p.m.: {V} leaves for lunch."), (0, "12:15 p.m.: {D} takes the washer."), (0, "1:15 p.m.: {D} texts."), (0, "1:20 p.m.: {V} says no."), (0, "1:45 p.m.: deputies recover the washer.")],
        identified: "A site camera.",
        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let dogTagScamV1 = SmallCases.make(
        key: "story.dogTagScam",
        category: .whiteCollar,
        headlines: ["Door-to-Door Seller Offered County 'Burn Permit' Stickers at $35 Each, Records Show None Issued", "Six Homeowners Hold Worthless Stickers"],
        law: "falsePretenses",
        spec: "Obtained property of {V} by deception, $35, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "On {DATE}, {D} knocked on doors in a rural subdivision and offered homeowners county burn permit stickers for $35 each, saying a new rule required them. Six homeowners paid. The county's fire marshal said no such sticker or fee existed. {V}, one buyer, kept the receipt and a photo of {D}'s van. {DL} says {D.he} believed the stickers were real because a friend sold them.",
        state: [E(.physical, 3, "Stickers", "Printed stickers that look like county permits."), E(.document, 2, "County Records", "No sticker or fee exists."), E(.statement, 2, "Homeowners", "Six paid $35."), E(.video, 1, "Doorbell Camera", "{D} at {V}'s door.")],
        defense: [E(.statement, 1, "Friend's Stickers", "{DL} says a friend sold {D.him} the stickers."), E(.document, 1, "Receipt Book", "A receipt book with {D}'s sales.")],
        role: "Homeowner",
        exam: [.direct("What happened at your door on {DATE}?", "\"{D} knocked and offered me a county burn permit sticker for $35, saying a new rule required it. I paid, and I kept the receipt.\""), .direct("What evidence do you have?", "\"The receipt, a photo of {D}'s van, and a doorbell camera clip of {D} at my door. The stickers look like county permits but aren't.\""), .direct("How did {D} come across to you?", "\"Polite and confident. {D} wore a collared shirt and said a county rule required a burn permit sticker for each home.\""), .direct("What did you pay and get?", "\"$35 cash for a printed sticker and a handwritten receipt. {D} said to put it on the mailbox.\""), .direct("What did you find when you checked?", "\"The county fire marshal said no such sticker or fee exists. Five other homeowners on my road had paid the same $35.\""), .direct("What did the sticker look like when you held it up to your car window?", "\"It had a county seal printed on it and a number, but the ink was faint and the edges were rough. It looked like something printed at home.\""), .cross("{DL} says a friend sold {D.him} the stickers, doesn't {D.he}?", "\"I can't know that. I only know what {D} told me at my door.\""), .cross("Did {DL} give you a receipt?", "\"Yes. A handwritten receipt. {D} wasn't hiding who {D.he} was.\""), .cross("Did {DL} wear a badge?", "\"Not that I noticed. {D} spoke like it was a new rule and I believed it.\""), .cross("Did {D} claim to work for the county?", "\"Not outright. {D} said it was a new county rule and let me assume.\""), .cross("Did {D} try to hide who {D.he} was?", "\"No. {D} left a receipt and parked a van in plain view.\"")],
        theory: ("{D} sold fake permit stickers door to door.", "A seller who believed the stickers were real."),
        allocution: "\"I let money decide it, and I can't take it back.\"",
        truths: ("{DL} wore a lanyard that looked like a county badge.", "{DL} printed the stickers at a copy shop."),
        defendant: [.direct("Where did you get the permit stickers?", "\"From a friend who sold them to me. I believed they were real, since the friend said they were required for burn permits.\""), .direct("Why did you sell them door to door?", "\"The friend said homeowners needed them. I sold them for $35 and wrote receipts in my receipt book. I wasn't hiding.\""), .direct("Did you know they were fake?", "\"No. If I had known, I would never have knocked on a door. I used my own van and my own name.\""), .direct("How did you start selling the stickers?", "\"A friend gave me a box of stickers and a script. The friend said homeowners needed them under a new rule and I could keep part of each sale.\""), .direct("How did you present it?", "\"I knocked, introduced myself, said the stickers were for burn permits, and offered a receipt. I did not wear any badge.\""), .direct("What did you do when you learned they were fake?", "\"I was horrified. I stopped, gave my receipt book to a deputy, and offered to refund every buyer.\""), .cross("The county says no such sticker exists, doesn't it?", "\"That's what I'm told. I was shocked. I didn't check with the county.\""), .cross("Six homeowners paid you $35, didn't they?", "\"Yes. I collected from six. I thought I was helping them comply.\""), .cross("You told {V} it was a new rule, didn't you?", "\"Yes. That's what my friend told me. I repeated it without checking.\""), .cross("You never checked with the county. Why?", "\"I trusted my friend. I should have called the fire marshal first.\""), .cross("Six people paid you $35 for a sticker that does not exist. Isn't that fraud?", "\"It looks that way, but I believed it was real. I am responsible for repeating it.\"")],
        openings: ("{D} went door to door in a rural subdivision selling burn permit stickers for $35, saying a new rule required them. The county says no such sticker exists, and six homeowners paid. The State will show the stickers, the doorbell camera, and the county records.", "The defense will present a seller who believed what a friend told {D.him}, kept a receipt book, and used {D.his} own van and name at every door."),
        closings: ("Six homeowners paid $35 each for stickers the county never issued, after being told a new rule required them. {V} kept the receipt and photographed the van.", "{D} was sold the stickers by a friend and kept receipts in the open. The State has not proved {D} knew the stickers were fake."),
        timeline: [(0, "10 a.m.: {D} begins knocking."), (0, "11 a.m.: {V} pays $35."), (0, "2 p.m.: five others pay."), (1, "{V} calls the fire marshal."), (2, "Deputies take statements.")],
        identified: "A doorbell camera.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .female])

    static let chemLawnV1 = SmallCases.make(
        key: "story.chemLawn",
        category: .publicOrder,
        headlines: ["Neighbor Writes a Word in Weed Killer Across Lawn, Brown Letters Spread After a Week", "Porch Camera Shows Late-Night Spraying"],
        law: "disorderly",
        spec: "Willfully injured property of {V}, a neighbor, with chemicals, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After a long dispute over a shared driveway, {V} woke on {DATE} to find a word burned in brown letters across the front lawn a week after a late-night spraying. A porch camera showed {D}, the next-door neighbor, walking the lawn with a backpack sprayer at 1 a.m. A jug of herbicide was in {D}'s garage. The lawn needed re-sodding at a cost of $620. {DL} says {D.he} was spraying weeds along the driveway and the wind carried it.",
        state: [E(.video, 3, "Porch Camera", "{D} sprays the lawn at 1 a.m."), E(.physical, 2, "Herbicide Jug", "In {D}'s garage, matching the lawn test."), E(.document, 2, "Re-Sod Estimate", "$620 to replace the lawn."), E(.forensic, 1, "Lawn Test", "Herbicide residue in the dead strip.")],
        defense: [E(.statement, 1, "Drift", "{DL} says the wind carried the spray."), E(.statement, 1, "Driveway Weeds", "{DL} says {D.he} was spraying weeds.")],
        role: "Neighbor",
        exam: [.direct("What was going on between you and {DL}?", "\"A long dispute over a shared driveway. {D} is my next-door neighbor, and we'd argued for about a month.\""), .direct("What did you find on {DATE}?", "\"A word burned in brown letters across my front lawn, about a week after a late-night spraying. The lawn needed re-sodding, an estimate of $620.\""), .direct("What does your porch camera show?", "\"{D} walking the lawn with a backpack sprayer at 1 a.m. A jug of herbicide was later found in {D}'s garage, and a lawn test found herbicide in the dead strip.\""), .direct("How long had the driveway fight gone on?", "\"Over a year. We argued about where the line ran and who should pay to repair it. It had gotten loud but never physical.\""), .direct("How did you see the lawn?", "\"On the morning of {DATE} brown letters were burned across the front lawn, about a week after the spraying. They spelled a word aimed at me.\""), .direct("What did the dead strip look like when you walked it that morning?", "\"It ran in a long straight band, about a foot wide, across the whole front lawn. The grass was brown and the edges were sharp.\""), .cross("{DL} says {D.he} was spraying weeds along the driveway, doesn't {D.he}?", "\"The driveway is next to my lawn, so I can see it's possible. But the dead part isn't along the driveway.\""), .cross("Does the wind blow there often?", "\"Sometimes. I can't say what the wind was that night. I was asleep.\""), .cross("Can the camera show what {DL} sprayed?", "\"No. It shows {D} walking the lawn with a sprayer. It can't show the pattern of the spray.\""), .cross("Could wind have carried herbicide from the driveway?", "\"Wind could carry some. But the damage looks like letters, not random drift.\""), .cross("What did the lawn test show?", "\"Herbicide residue in the dead strip. It matched the jug in {D}'s garage.\"")],
        theory: ("{D} used weed killer to write a message on a neighbor's lawn.", "A neighbor whose spray drifted."),
        allocution: "\"I understand why people were afraid. I'm sorry.\"",
        truths: ("{DL} had a stencil hidden under the sprayer's tray.", "{DL} sprayed in straight lines, not along the driveway."),
        defendant: [.direct("What were you doing at 1 a.m.?", "\"Spraying weeds along the driveway. I'd been fighting weeds there for weeks. I did it at night because it's cooler.\""), .direct("Did you write a word on {V}'s lawn?", "\"No. The wind carried the spray onto the lawn. I never meant to hit it, and I never wrote anything.\""), .direct("Why was herbicide in your garage?", "\"I use it on weeds. Most people have a jug in the garage. It's not unusual.\""), .direct("What were you doing at 1 a.m. with a sprayer?", "\"Killing weeds along the driveway edge. I do it at night when it is calm and the sun will not burn it off.\""), .direct("What happened with the wind?", "\"A gust came up while I was spraying and blew the mist onto the grass next door. I did not notice anything until the lawn turned brown.\""), .direct("How do you feel about the lawn?", "\"Embarrassed. I never wanted to hurt {V}'s lawn. I offered to pay for sod.\""), .cross("You and {V} had a dispute over the driveway, didn't you?", "\"Yes. A long one. But I didn't take it out on the grass.\""), .cross("The lawn test found herbicide, didn't it?", "\"Yes. I'm not surprised. The spray drifted there.\""), .cross("You walked across {V}'s lawn with the sprayer, didn't you?", "\"I may have stepped on the edge. I wasn't aiming at the lawn.\""), .cross("The dead area forms letters. Does wind write words?", "\"I do not know how that happened. I did not write anything.\""), .cross("You and {V} had a long fight. Doesn't that give a reason to spray?", "\"It gives a reason to be careful. I would not damage a lawn over a driveway.\"")],
        openings: ("After a month-long driveway dispute, {V} woke to a word burned across the front lawn. A porch camera shows {D}, the next-door neighbor, walking the lawn with a sprayer at 1 a.m. The State will show the video, the herbicide jug, and the lawn test.", "Jurors will also see a neighbor spraying weeds along a driveway at night, drifting wind, and a jug of weed killer that sits in most garages."),
        closings: ("A dispute, a sprayer at 1 a.m., a jug in {D}'s garage, and a word burned into the lawn. The re-sod will cost $620.", "Weeds, a driveway, and a gust of wind. The State has not proved {D} wrote a word on the lawn rather than spraying weeds."),
        timeline: [(-30, "The driveway dispute starts."), (0, "1 a.m.: {D} sprays."), (7, "The brown letters appear."), (8, "{V} reviews the porch camera."), (9, "The lawn test is done.")],
        identified: "A porch camera.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let pewShoveV1 = SmallCases.make(
        key: "story.pewShove",
        category: .violent,
        headlines: ["Easter Sunday Parking Dispute Ends With Volunteer Shoved Into a Car Door", "Church Lot Camera Records Push"],
        law: "simpleAssault",
        spec: "Assaulted {V} by pushing {V.him}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "On Easter Sunday, {DATE}, {D} tried to park in a space the church had reserved for the elderly. A volunteer, {V}, told {D} the space was reserved. {D} pushed {V} in the chest and into the open door of a car. {V} had a bruise on the ribs. A church lot camera caught the push. {DL} says {D.he} was late and that {V} stepped in front of the car.",
        state: [E(.video, 3, "Lot Camera", "{D} pushes {V} into a car door."), E(.document, 2, "Medical Note", "A bruise on the ribs."), E(.statement, 2, "Witness", "A parishioner saw the push."), E(.physical, 1, "Reserved Sign", "The space was posted as reserved.")],
        defense: [E(.statement, 1, "Stepped In Front", "{DL} says {V} stepped in front of the car."), E(.statement, 1, "Late", "{DL} was late for the service.")],
        role: "Church volunteer",
        exam: [.direct("What were you doing at the church lot on Easter Sunday?", "\"I was a volunteer helping direct parking. One space was reserved for the elderly, and I was keeping it open for them.\""), .direct("What did you tell {D}?", "\"That the space was reserved. A sign posted the reservation, and I stepped up to the car to say so.\""), .direct("What happened then?", "\"{D} pushed me in the chest and into the open door of a car. I had a bruise on my ribs afterward.\""), .direct("What was your job at the church lot?", "\"I was a volunteer parking guide on Easter Sunday, helping families find space and keeping the spots near the door open for older members.\""), .direct("How was the space marked?", "\"With a sign and two cones. A white placard said reserved for seniors and the handicapped.\""), .direct("What did {D} do?", "\"{D} drove forward toward the space. I stepped near to guide, and {D} stopped and got out. {D} shoved me hard in the chest into an open car door.\""), .cross("{D} says you stepped in front of the car, doesn't {D.he}?", "\"I was standing near the space to guide cars. I did not step into the path of a moving car.\""), .cross("Was {D} late for the service?", "\"I do not know. {D} may have been in a hurry, but that did not give anyone the right to push me.\""), .cross("Did anyone else see the push?", "\"Yes. A parishioner saw it, and the lot camera caught it clearly.\""), .cross("Did you step in front of {D}'s car?", "\"I was standing beside the space to point cars. I did not step into the lane.\""), .cross("How badly were you hurt?", "\"A bruise on the ribs, which I had checked by a doctor that afternoon. It hurt to breathe for a few days.\"")],
        theory: ("{D} shoved a volunteer over a parking space.", "A late driver reacting to a blocked car."),
        allocution: "\"I lost my temper, and I'm sorry for what I did.\"",
        truths: ("{DL} ignored the reserved sign and drove forward.", "{V} stepped in front of the car as {DL} was pulling in."),
        defendant: [.direct("Did you push the volunteer?", "\"Yes, I did. I was late for the Easter service, and I pushed when {V} stepped in front of the car.\""), .direct("Why did you try to park in that space?", "\"It was the only open spot near the door, and I was running late. I did not stop to read the sign.\""), .direct("What do you say about the reserved sign?", "\"I did not notice it at first. I saw it only after the argument, and I should have looked.\""), .direct("Why were you in a hurry?", "\"I was late for the Easter service. We had family waiting and the lot was nearly full.\""), .direct("What did you see at the space?", "\"An open spot near the door. I did not notice the sign until I was nearly in it.\""), .direct("What happened when the volunteer approached?", "\"The volunteer stepped near my car. I braked, got out in a rush, and pushed. I did not mean for {V.him} to hit the door.\""), .cross("The sign was posted, wasn't it?", "\"Yes. It was posted. I drove forward anyway. That was my mistake.\""), .cross("The camera shows you pushing {V} into a car door, doesn't it?", "\"It does. I did not mean for {V.him} to hit the door. I was upset and I reacted.\""), .cross("{V} had a bruised rib. Do you regret that?", "\"Yes. I feel awful about it. It was Easter Sunday, and I let anger get the better of me.\""), .cross("You pushed a church volunteer on Easter morning. Why?", "\"I was stressed and ashamed of arriving late. It was no excuse.\""), .cross("A parishioner and a camera saw the push. Do you dispute it?", "\"No. It happened. I am sorry for it.\"")],
        openings: ("On Easter Sunday, {D} tried to park in a space reserved for the elderly. When {V}, a church volunteer, said so, {D} pushed {V} in the chest and into a car door, and the lot camera caught it.", "The defense case is that {D} was late, did not notice the sign, and reacted when {V} stepped in front of the car, with no plan to hurt anyone."),
        closings: ("A reserved sign, a volunteer who said so, and a push into a car door on camera. {V} was bruised on Easter Sunday for doing a kindness.", "A late driver, a volunteer who stepped in front of the car, and one push that {D} regrets. The State must prove the push was more than a reaction."),
        timeline: [(0, "9:50 a.m.: {D} arrives late."), (0, "9:52 a.m.: {V} says the space is reserved."), (0, "9:53 a.m.: the push."), (0, "10 a.m.: deputies are called."), (1, "{V} sees a doctor.")],
        identified: "A church lot camera.",
        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let buffetCarryoutV1 = SmallCases.make(
        key: "story.buffetCarryout",
        category: .property,
        headlines: ["Wedding Guests Stuff Foil Pans and Coolers With Catered Entrees at Reception's End", "Caterer Counts Four Missing Trays After Event"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a catering company, valued at $120, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A caterer set out entrees for a wedding reception, with a written agreement that leftovers belonged to the caterer. When the reception ended on {DATE}, a staff member saw {D} fill two foil pans from the chafing dishes and carry them to a cooler in {D}'s car. The caterer counted four missing trays worth $120. {DL} says the host said leftovers were free for guests to take.",
        state: [E(.video, 3, "Venue Camera", "{D} fills foil pans and takes them to a car."), E(.document, 2, "Catering Agreement", "Leftovers belong to the caterer."), E(.physical, 2, "Cooler", "A cooler with the caterer's foil pans."), E(.statement, 1, "Staff Member", "Saw {D} filling the pans.")],
        defense: [E(.statement, 1, "Host Said Free", "{DL} says the host said guests could take leftovers."), E(.statement, 1, "Everyone Did", "Other guests also left with food.")],
        role: "Caterer",
        exam: [.direct("What was the arrangement at the reception on {DATE}?", "\"I catered a wedding reception with a written agreement that leftovers belonged to the caterer. That's in the catering agreement.\""), .direct("What did your staff see?", "\"When the reception ended at about 9, a staff member saw {D} fill two foil pans from the chafing dishes and carry them to a cooler in {D}'s car.\""), .direct("What was missing?", "\"Four trays, worth about $120. The cooler had my foil pans in it. The venue camera shows {D} filling the pans.\""), .direct("What did the written agreement say about the food?", "\"It said anything left after the reception belonged to me as the caterer, and the host signed it before the event. I keep a copy in my binder and showed it to deputies.\""), .direct("How many entrees did you set out and what was your plan for leftovers?", "\"Six chafing dishes of chicken, beef, and sides. I planned to package what was left for my staff meal and the next day's tasting.\""), .direct("How did you find out about the missing trays?", "\"After packing up, I counted my foil pans and came up four short. A staff member said {D} had been filling pans from the line at about nine.\""), .cross("{DL} says the host said leftovers were free, doesn't {D.he}?", "\"The host may have said so. But the host didn't own the leftovers. The agreement gave them to me.\""), .cross("Did other guests leave with food?", "\"Some did. I'm told others took a bit. But not trays filled into a cooler.\""), .cross("Did you tell guests to leave the food alone?", "\"I didn't have a sign up. In hindsight, yes. I was packing up the kitchen.\""), .cross("Did you ever tell guests they could not take food?", "\"No. I did not post a sign, and I did not announce that leftovers were mine. I was busy breaking down the line.\""), .cross("How did you place a value of $120 on the four trays?", "\"I figured by cost and portions. Four full trays of that menu cost me about $120 to prepare.\"")],
        theory: ("{D} carried off a caterer's trays.", "A guest who thought leftovers were free."),
        allocution: "\"I took what wasn't mine, and I'm sorry for it.\"",
        truths: ("{DL} brought a cooler and foil pans into the reception.", "{DL} filled the pans after the caterer had begun packing up."),
        defendant: [.direct("Why did you fill the foil pans?", "\"The host said leftovers were free for guests to take. Other guests were also leaving with food. I took some home.\""), .direct("Whose cooler was that?", "\"Mine. I keep a cooler in my car. I put the pans in it.\""), .direct("Did you know the caterer owned the leftovers?", "\"No. I didn't know about the agreement. I believed the host, who was paying.\""), .direct("How did you come to be at the reception?", "\"I was a guest, a friend of the host. We ate dinner, danced, and I stayed until the end.\""), .direct("What exactly did the host say about leftovers?", "\"As the party wound down, the host stood up and told people to grab food to take home. I heard it myself.\""), .direct("What did you do after hearing that?", "\"I went to the line with two foil pans and filled them. Other guests were doing the same with smaller containers.\""), .cross("You filled two foil pans, didn't you?", "\"Yes. I took a good amount. It was a big reception.\""), .cross("The caterer lost four trays, didn't {V.he}?", "\"I've heard that. I didn't count. I thought they were leftovers.\""), .cross("The reception ended at 9, correct?", "\"Yes. I took the food just afterward. I wasn't sneaking.\""), .cross("The caterer's staff told you the leftovers belonged to the caterer, didn't they?", "\"No one told me that. I heard only the host. If a staff member had said something, I would have stopped.\""), .cross("You filled two full pans with a cooler waiting in your car. Isn't that more than a guest takes?", "\"I like to be prepared. I brought a cooler because I assumed there would be leftovers, and I took what seemed fair.\"")],
        openings: ("A caterer's written agreement said leftovers belonged to the caterer. After a wedding reception ended, {D} filled two foil pans from the chafing dishes and carried them to a cooler in {D}'s car. The State will show the camera and the agreement.", "The defense will point you to a guest who was told by the host that leftovers were free, who saw others leave with food, and who took some openly."),
        closings: ("A written agreement, two foil pans filled at the end of the night, and a cooler waiting in {D}'s car with the caterer's trays inside. That is a planned taking, not a casual guest's plate.", "The host told guests to take leftovers, other guests did the same, and {D} loaded food in plain view of staff. The State has not proved {D} knew the food was not free for the taking."),
        timeline: [(0, "9 p.m.: the reception ends."), (0, "9:20 p.m.: {D} fills the pans."), (0, "9:30 p.m.: a staff member sees the cooler."), (0, "10 p.m.: the caterer counts the trays."), (1, "The caterer reports it.")],
        identified: "A venue camera.",
        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let salonWalkoutV1 = SmallCases.make(
        key: "story.salonWalkout",
        category: .property,
        headlines: ["Nail Salon Customer Slips Out Back After Gel Set and Pedicure", "Back Door Camera Catches Customer Leaving Without Paying $210"],
        law: "misdLarceny",
        spec: "Stole services valued at $210 from {V}, a nail salon, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} booked a gel manicure and a pedicure at a nail salon on {DATE} and gave a phone number at the desk. At 4:05 p.m., while the technician fetched a towel, {D} walked out the back door. The service ticket came to $210. {D} says {D.he} went to find an ATM and meant to return.",
        state: [E(.video, 3, "Back Door Camera", "{D} leaves through the rear door at 4:05 p.m. with one flip-flop on."), E(.document, 2, "Service Ticket", "Manicure and pedicure, $210, unpaid."), E(.document, 2, "Appointment Record", "The booking lists a phone number that rings to a disconnected line."), E(.statement, 2, "Technician", "Went for a towel and returned to an empty chair.")],
        defense: [E(.document, 1, "ATM Receipt", "A $200 cash withdrawal at an ATM two blocks away at 4:12 p.m."), E(.statement, 1, "Meant to Return", "{DL} says the front door was locked when {D.he} came back.")],
        role: "Nail technician",
        exam: [.direct("What did you do for {D} at the salon?", "\"A gel manicure and a pedicure. The service ticket came to $210. I went to fetch a towel in the middle of it.\""), .direct("What happened while you were away?", "\"I came back to an empty chair. {D} had walked out the back door, with one flip-flop on, at about 4:05.\""), .direct("What does the back door camera show?", "\"{D} leaving at 4:05 p.m. through the rear door. The booking also lists a phone number that rings to a disconnected line.\""), .direct("What was the service {D} booked?", "\"A gel manicure and a full pedicure with a soak. {D} gave a name and a phone number at the front desk and chose a color.\""), .direct("How long was {D} in the chair before you stepped away?", "\"About an hour and ten minutes. I was finishing the second foot when I went to the back for a fresh towel.\""), .direct("What did you do when you found the chair empty?", "\"I checked the restroom and the front, then the back door. It was open, and a flip-flop was lying outside. I called the owner and then deputies.\""), .cross("{D} says {D.he} went to find an ATM, doesn't {D.he}?", "\"Yes. {D} said so. I did not hear that from {D} before; it came after.\""), .cross("Did {D} try the front door?", "\"I understand a customer in one flip-flop stood at the front door and then left. The front door sticks during the afternoon break.\""), .cross("Did {D} ever return to pay?", "\"No. {D} never came back. The $210 ticket is still unpaid.\""), .cross("Did {D} tell you about an ATM?", "\"No. Not a word. I only heard that later, after the camera and the ticket were reviewed.\""), .cross("Do you know whether the front door was open when {D} left?", "\"I was in the back with a customer, so I do not know whether the front door was locked or open at that moment.\"")],
        defenseRole: "Owner of the shop next door",
        defenseExam: [.direct("Was the salon's front door latched that afternoon?", "\"It sticks on the afternoon break, so you have to knock to be let in. It is a known problem at that salon.\""), .direct("Did you see {D} that afternoon?", "\"I saw a customer in one flip-flop standing at the front door of the salon, and then the person left.\""), .direct("Did you see {D} come back to the salon later?", "\"No. I did not see {D} come back that afternoon. I was in my shop for the rest of the day.\""), .direct("How long have you owned your shop next door?", "\"Nine years. Our back doors face the same alley, so I see who comes and goes from the salon.\""), .direct("What did you see in the alley that afternoon?", "\"A customer in one flip-flop walked toward the street. I assumed the person was in a hurry.\""), .direct("What do you know about the salon's front door?", "\"On the afternoon break the owner latches it so walk-ins wait for knocks. It sticks if you push, and customers have trouble.\""), .cross("Did you hear anyone call out to the customer at the door?", "\"No. I did not hear anyone call out. It was quiet, and I only saw the customer standing there.\""), .cross("How long was the customer at the front door?", "\"Only a short time, perhaps a minute. I was busy with my own customers and did not watch long.\""), .cross("Did you know the customer who was standing at the door?", "\"No. I did not know that person. I only noticed because of the single flip-flop.\""), .cross("Did you speak with the customer?", "\"No. We did not exchange a word. I was holding a delivery and did not think more of it.\""), .cross("Did you tell the salon about what you saw?", "\"Not until deputies asked me a few days later.\"")],
        theory: ("{D} took the service and left without paying.", "{D} went for cash and found the door locked."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("{DL} drove home after the ATM and never returned.", "The salon's front door was latched during the afternoon break."),
        defendant: [.direct("Did you leave the salon without paying?", "\"Yes. I walked out the back door to find an ATM, because I realized I did not have enough cash.\""), .direct("Why did you leave through the back door?", "\"I tried the front door first, but it was stuck. The back door was open, and I was in a hurry.\""), .direct("Did you mean to return and pay?", "\"Yes. I meant to come back. I drove home after the ATM and never returned. I was ashamed.\""), .direct("What went through your mind when you realized you did not have enough cash?", "\"I thought I had cards in my bag but they were in the car. I felt rushed and wanted to run out to an ATM and come right back.\""), .direct("Where did you go after leaving the back door?", "\"To an ATM two blocks away. I withdrew $200 at about 4:12 and walked back toward the shop.\""), .direct("Why did you not go back in?", "\"The front door looked closed and I felt foolish for leaving. I sat in the car for a while and then drove home.\""), .cross("You left with one flip-flop on, didn't you?", "\"Yes. I was in a rush. I did not take time to put the other one on.\""), .cross("The phone number you gave rings to a disconnected line, doesn't it?", "\"It does. I gave an old number by mistake. I did not mean to hide anything.\""), .cross("You could have told the technician you needed an ATM, couldn't you?", "\"Yes. I should have. I was embarrassed, and I walked out instead.\""), .cross("$200 does not cover a $210 ticket. Were you even planning to pay in full?", "\"I figured I could add a card for the rest. I should have walked in and said so.\""), .cross("Why would you give a phone number that does not ring?", "\"I mixed up my numbers at the desk. I did not intend to make it hard to reach me.\"")],
        openings: ("{D} booked a $210 manicure and pedicure at a nail salon and gave a phone number that rings to a dead line. At 4:05 p.m., while the technician fetched a towel, {D} walked out the back door in one flip-flop.", "Jurors will hear that {D} went to find an ATM, that the front door sticks during the afternoon break, and that {D} meant to return."),
        closings: ("A service ticket for $210, a dead phone number, and a customer who left through the back door while the technician was away. {D} never came back to pay.", "A stuck front door, a customer in one flip-flop, and an ATM errand. The State must prove {D} meant to leave without paying from the start."),
        timeline: [(0, "3:00 p.m.: {D} sits for the manicure and pedicure."), (0, "4:05 p.m.: {D} leaves by the back door."), (0, "4:12 p.m.: the ATM withdrawal."), (1, "The salon sends the back door footage to the Sheriff's Office.")],
        identified: "The booking phone number and the back door camera identify {D}.",
        notDone: ["No one checked the salon's front door latch.", "The ATM withdrawal was never matched to a return trip to the salon."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let moversHoldV1 = SmallCases.make(
        key: "story.moversHold",
        category: .whiteCollar,
        headlines: ["Car Hauler Holds Customer's Sedan at Destination Until Extra $600 Is Paid in Cash", "Written Estimate and Texts Contradict the Demand"],
        law: "falsePretenses",
        spec: "Obtained $600 from {V} by deception, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} hired {D}'s car hauling company for a flat $1,100 to deliver a sedan across the state, as the written estimate and text messages showed. On {DATE}, when the hauler reached the destination, {D} refused to unload the car unless {V} paid $600 more in cash for 'fuel and fees.' {V} paid. {DL} says the extra fees were in the terms on the back of the contract.",
        state: [E(.document, 3, "Written Estimate", "A flat price of $1,100."), E(.digital, 2, "Text Messages", "'All inclusive' in {D}'s own message."), E(.document, 2, "Bill of Lading", "No extra fees listed."), E(.statement, 1, "Witness", "Heard the demand at delivery.")],
        defense: [E(.statement, 1, "Back of Contract", "{DL} says the terms allowed extra fees."), E(.document, 1, "Fuel Receipts", "Fuel costs were high that week.")],
        role: "Customer",
        exam: [.direct("What did you hire {D}'s company to do?", "\"Deliver a sedan across the state. The written estimate and the text messages both set a flat price of $1,100.\""), .direct("What did {D}'s own message say?", "\"'All inclusive.' That is in {D}'s text to me, and the bill of lading lists no extra fees.\""), .direct("What happened at delivery?", "\"{D} refused to unload the car unless I paid $600 more in cash for 'fuel and fees.' I paid because I needed the car.\""), .direct("What did the contract and the estimate say about the price?", "\"The estimate said $1,100 flat for the haul. A text from {D} said 'All inclusive,' and the bill of lading listed no extra fees.\""), .direct("Where did the delivery take place and who was present?", "\"In the driveway of my new home. A neighbor was helping me carry boxes and heard what {D} said about the extra cash.\""), .direct("What did {D} say about the extra money?", "\"{D} said fuel prices had gone up and there were fees. {D} held the keys and said the car would stay on the truck until I paid $600 more in cash.\""), .cross("{D} says the extra fees were in the terms on the back of the contract, doesn't {D.he}?", "\"Yes. But the estimate and the texts said all inclusive. I never saw terms that said that.\""), .cross("Did you sign the back of the contract?", "\"I signed the front. I did not read the back, and I do not recall any extra fee in it.\""), .cross("Did {D} threaten you?", "\"No. {D} just kept the keys and would not unload. A witness heard the demand.\""), .cross("Did you consider refusing to pay?", "\"Yes. But the car was my only vehicle and I needed it for work the next morning, so I paid.\""), .cross("Did you see the back of the contract before the delivery?", "\"No. I signed the front page and did not flip it over.\"")],
        theory: ("{D} held a car hostage to collect extra money.", "A hauler relying on contract terms."),
        allocution: "\"I knew better. I want to make it right.\"",
        truths: ("{DL} had demanded extra fees from two earlier customers.", "{DL} refused to hand over the keys until paid."),
        defendant: [.direct("Why did you ask for $600 more?", "\"For fuel and fees. They were in the terms on the back of the contract, and I believed I was entitled to them.\""), .direct("Did you tell {V} about the extra fees before delivery?", "\"I may not have been clear. I assumed the contract made it plain, and I did not repeat it.\""), .direct("Why did you hold the keys?", "\"I wanted to be paid what I thought I was owed. It is how I run my business.\""), .direct("How long have you hauled cars?", "\"Eleven years, mostly across the state on a single-car trailer. I handle fuel, tolls, and any repairs along the way.\""), .direct("What happened with fuel prices that week?", "\"They jumped several times, and my trip cost far more than the quote allowed. I was already losing money before I reached the delivery.\""), .direct("What did you tell {V} at the driveway?", "\"That my agreement included fuel and fees and that I needed $600 to cover the added costs. I kept the keys until we settled it.\""), .cross("Your own text said 'all inclusive,' didn't it?", "\"It did. I used those words loosely. I meant the main haul.\""), .cross("The bill of lading lists no extra fees, does it?", "\"It does not. I should have listed them there.\""), .cross("You demanded the cash from two earlier customers too, didn't you?", "\"I asked for extra fees before. I thought they were fair.\""), .cross("You wrote 'all inclusive' in a text. How is that not a promise of a flat price?", "\"I used the phrase loosely. I assumed the back of the contract made the extra charges clear.\""), .cross("You held the keys of a car that was not yours. Isn't that coercion?", "\"I believed I had a right to be paid what I was owed. Looking back, I see how the keys felt to {V}.\"")],
        openings: ("{V} hired {D}'s hauling company for a flat $1,100 to deliver a sedan, with 'all inclusive' in {D}'s own text. At delivery, {D} refused to unload the car unless {V} paid $600 more in cash.", "The defense evidence will establish that fuel and fees were in the terms on the back of the contract and that {D} believed the extra charge was owed."),
        closings: ("A written estimate for $1,100, a text promising 'all inclusive,' and a hauler who held the keys until $600 more was paid in cash. That is a demand backed by the control of someone else's car.", "Fuel costs spiked that week, and the back of the contract allowed extra fees. {D} asked for money owed under those terms, and the State cannot show that {D} meant to take anything unlawfully."),
        timeline: [(-14, "{V} books the car hauler."), (-7, "{D} texts 'all inclusive'."), (0, "{D} reaches the destination."), (0, "{D} demands $600."), (1, "{V} reports it.")],
        identified: "A written estimate.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let valetGloveboxV1 = SmallCases.make(
        key: "story.valetGlovebox",
        category: .property,
        headlines: ["Hotel Valet Opens Center Console and Takes $350 Cash Envelope", "Garage Camera Shows Valet Open Console Minutes After Parking"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a hotel guest, valued at $350, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} gave a hotel valet the keys to a rental car at 6:30 p.m. on {DATE} and left a bank envelope with $350 in the center console. When {V} retrieved the car at 9 p.m., the envelope was gone and the console lid was left open. The garage camera shows {D}, a valet, open the console at 6:42 p.m. {D} says the envelope was not there and {D.he} was looking for a charging cable.",
        state: [E(.video, 3, "Garage Camera", "At 6:42 p.m. {D} opens the center console and puts something in a jacket pocket."), E(.document, 2, "Valet Ticket", "Keys received at 6:30 p.m. and parked at 6:40 p.m. by {D}."), E(.statement, 2, "{V}", "The envelope held seven $50 bills from a bank withdrawal that afternoon."), E(.document, 2, "Bank Slip", "A $350 withdrawal at 3 p.m. in {V}'s name.")],
        defense: [E(.statement, 1, "Charging Cable", "{DL} says {D.he} was looking for a charger cable."), E(.document, 1, "Lost and Found Log", "Two phones and a cable were logged at the valet stand that week.")],
        role: "Hotel guest",
        exam: [.direct("What did you leave in the rental car?", "\"A bank envelope with $350 in the center console. I had withdrawn it at 3 p.m., in seven $50 bills.\""), .direct("What did you find when you got the car back?", "\"At 9 p.m. the envelope was gone and the console lid was left open. I called the hotel and deputies.\""), .direct("What does the garage camera show?", "\"At 6:42 p.m., {D} opens the center console and puts something in a jacket pocket.\""), .direct("Why did you leave cash in the console?", "\"I had withdrawn $350 that afternoon for a deposit on a family trip. I tucked the envelope in the console and forgot about it when I handed over the keys.\""), .direct("How did the valet process go at 6:30?", "\"I gave the keys to a valet and got a ticket. I walked into the lobby, checked in, and did not see the car again until nine.\""), .direct("What did you do when you found the envelope missing?", "\"I looked in the console and the glove box, then asked the valet stand. A manager pulled the garage camera while I waited.\""), .cross("{D} says there was no envelope and {D.he} was looking for a cable, doesn't {D.he}?", "\"That is what {D} says. I know valets look for cables sometimes. But the envelope was there when I handed over the keys.\""), .cross("Did you tell the valet about the cash?", "\"No. I did not mention it. I should have taken it with me.\""), .cross("Did you see {D} take anything?", "\"No. I only saw the camera later. It shows something going into a pocket.\""), .cross("Did you tell the valet about the envelope?", "\"No. I did not say anything. It was my mistake to leave it.\""), .cross("Are you sure it was exactly seven $50 bills?", "\"Yes. The bank slip shows $350, and I counted the bills in the car before I put them in the envelope.\"")],
        defenseRole: "Hotel valet coworker",
        defenseExam: [.direct("Do guests leave charging cables in the console?", "\"All the time. We look for them when we tag the keys, because guests ask us to plug phones in.\""), .direct("Do guests leave cash in the console too?", "\"Sometimes. We see envelopes and loose bills now and then. We are supposed to leave them where they are.\""), .direct("Did you see {D} on the evening of the incident?", "\"I saw {D} parking cars on a normal shift. It was an ordinary evening at the hotel garage.\""), .direct("How long have you worked as a valet?", "\"Six years at this hotel. We train new people on keys, tickets, and what to do with personal items.\""), .direct("What do you do when you find personal items in a car?", "\"We log anything valuable and give it to the guest at pickup. Phones and cables go to the lost and found log.\""), .direct("Did you see anything in {D}'s behavior that night?", "\"No. {D} parked cars like always and checked in with the manager at the end of the shift.\""), .cross("Did you see {D} open the center console of that car?", "\"No. I did not see it. I was parking cars of my own and was not watching {D}.\""), .cross("Would a valet take a cable and put it in a pocket?", "\"Sometimes. A cable can end up in a jacket pocket. It would be a small thing.\""), .cross("Do you know whether {D} found an envelope?", "\"No. I have no idea. I only know about cables and normal practice.\""), .cross("Do valets sometimes pocket loose cash?", "\"It is against the rules. If it happens, it is reported. I am not saying it never has, but I have not seen it.\""), .cross("Did you see {D} open the console?", "\"No. I was parking my own car. I learned about it from the manager.\"")],
        theory: ("{D} took cash from a guest's console.", "{D} was searching for a charger."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} had an envelope in a jacket pocket afterward.", "The console had a phone cable that {DL} pulled out."),
        defendant: [.direct("Did you take the envelope from the console?", "\"No. There was no envelope. I opened the console to find a phone cable and took the cable.\""), .direct("What did you put in your pocket?", "\"A charging cable. A guest had left one in the console, and I took it to charge my phone later.\""), .direct("Why did you open the console at 6:42?", "\"To look for a cable, as I do with many cars. It was part of routine when I parked.\""), .direct("How many cars do you park in a shift?", "\"Between sixty and ninety. We keep a routine of tagging keys, moving cars, and checking for personal items.\""), .direct("Why do you check consoles?", "\"Because guests leave phone chargers and sunglasses there, and a charger helps us if we need to run the engine. I do it with most cars.\""), .direct("What did you find in that console?", "\"A charging cable plugged into the port. I unplugged it and tucked it in my jacket to keep it from falling out.\""), .cross("The camera shows something going into your jacket pocket, doesn't it?", "\"Yes. It was a cable. I can show you the cable.\""), .cross("You never told the guest about the cable, did you?", "\"No. I should have left it. I did not think it mattered.\""), .cross("Seven $50 bills vanished from that console. Who took them?", "\"I do not know. I did not take them.\""), .cross("You put something in your pocket and the envelope disappeared. Isn't that a straight line?", "\"It is a line to a cable. I did not see any envelope, and I would not take money from a guest.\""), .cross("Why did you leave the console lid open?", "\"I was moving fast and did not close it. I know that looks sloppy.\"")],
        openings: ("A hotel guest left a bank envelope with $350 in a rental car's console and gave the keys to a valet. At 6:42 p.m. a garage camera shows {D}, the valet, open the console and pocket something, and the envelope was gone.", "By the end of this trial, the proof will show that valets routinely look for charging cables, that a cable was in the console, and that {D} took a cable and not cash."),
        closings: ("Seven $50 bills in an envelope, a console opened at 6:42, something into a jacket pocket on camera, and an empty console at 9 p.m. {D} was the only one in the car.", "A valet who opened a console for a charging cable, as valets do. The State has a camera and a pocket, but no one saw {D} take any cash."),
        timeline: [(0, "3:00 p.m.: {V} withdraws $350."), (0, "6:30 p.m.: {V} hands over the keys."), (0, "6:42 p.m.: {D} opens the console."), (0, "9:00 p.m.: {V} finds the envelope gone.")],
        identified: "The valet ticket and the garage camera identify {D}.",
        notDone: ["The envelope was never searched for in the garage.", "No one asked whether another valet had the keys before {DL}."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let rentalTiresV1 = SmallCases.make(
        key: "story.rentalTires",
        category: .whiteCollar,
        headlines: ["Moving Truck Returned With Mismatched Tires After Weekend Rental", "Tire Date Codes Show Truck Rode on Old Rubber"],
        law: "falsePretenses",
        spec: "Obtained property of {V}, a truck rental company, by deception, valued at $1,200, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} rented a box truck on a Friday and returned it Monday on {DATE}. The yard's pickup photos show six matching tires, but the return inspection found two rear tires with date codes eight years older and worn to the cords. The company says the good tires were swapped. {D} says a roadside shop replaced a flat during the move.",
        state: [E(.document, 3, "Pickup Photos", "Six matching tires with the same brand and date code at pickup."), E(.physical, 3, "Return Inspection", "Two rear tires with date codes eight years old and worn to the cords."), E(.document, 2, "Tire Invoice", "The company paid $1,200 for the pair that were gone."), E(.statement, 2, "Yard Inspector", "The inspector signed off on the tires on Friday afternoon.")],
        defense: [E(.statement, 1, "Roadside Flat", "{DL} says a roadside shop fixed a flat and put on spares."), E(.document, 1, "Mileage", "The truck logged 310 miles over the weekend.")],
        role: "Truck yard inspector",
        exam: [.direct("What did you sign off on at pickup?", "\"I checked the truck on Friday afternoon. Pickup photos show six matching tires with the same brand and date code.\""), .direct("What did you find at return?", "\"Two rear tires with date codes eight years older, worn down to the cords. The good tires had been swapped.\""), .direct("What did the company have to pay?", "\"$1,200 for the replacement pair. The invoice is in our file.\""), .direct("What did your pickup photos record?", "\"Six tires with the same brand and date code, treads even, and no cord showing. I took them Friday afternoon and signed the inspection sheet.\""), .direct("How did you realize two tires had been replaced?", "\"At return, the rear pair had a code from eight years earlier and treads worn to the cords. The brand logos also differed.\""), .direct("How many miles were put on the truck?", "\"310 over the weekend. That fits a move across town with a few trips, not a long haul.\""), .cross("{D} says a roadside shop replaced a flat during the move, doesn't {D.he}?", "\"Yes. A roadside shop did replace one flat. I will agree that it is possible.\""), .cross("Did the shop replace both rear tires?", "\"I understand only one. But two rear tires were swapped.\""), .cross("Could {D} have had a flat on the road?", "\"Yes, it can happen. That would explain one tire, not two with different date codes.\""), .cross("Did you check the spare tire at pickup?", "\"I did, and it was in the rack under the bed. At return the spare was missing.\""), .cross("Is it possible a roadside shop put on older tires as a stopgap?", "\"Yes. A shop could mount a spare, and that would explain one. Two rear tires being worn to cords is harder to explain.\"")],
        defenseRole: "Mobile tire shop worker",
        defenseExam: [.direct("Did you work on a truck for {D} that weekend?", "\"Yes. I fixed a flat on a box truck near the highway. I put on a spare tire I had in my van.\""), .direct("Did you replace both rear tires?", "\"Only one. I swapped the flat with a spare. I did not touch the other rear tire.\""), .direct("How did {D} pay you?", "\"Cash, and I did not write a receipt. I do not usually write one for a quick roadside job.\""), .direct("How does your mobile tire service work?", "\"I drive to the location, jack up the vehicle, swap or patch the tire, and take payment on the spot.\""), .direct("What exactly did you do for {D}?", "\"I replaced one rear tire that had blown out. I mounted a spare from my stock that held air and told {D} to get it checked.\""), .direct("How did {D} react?", "\"Calm and in a hurry. {D} paid cash and thanked me. The whole thing took about thirty minutes.\""), .cross("What did the spare look like?", "\"Old, but it held air. I would not have called it good, but it got the truck moving.\""), .cross("How worn was the spare?", "\"Quite worn. I did not check the date code. It was a stopgap for a flat.\""), .cross("Did you see the other rear tire?", "\"I looked at it briefly. It seemed worn but not to the cords, which is why I did not mention it.\""), .cross("Do you keep records of jobs?", "\"Sometimes in a notebook. I did not write one for this job, and That is on me.\""), .cross("You cannot say where the other rear tire came from, can you?", "\"No. I replaced only the flat that {D} had that day. I never touched the other rear tire and did not see where it came from.\"")],
        theory: ("{D} swapped good tires for old ones.", "A roadside flat and honest repair."),
        allocution: "\"I let money decide it, and I can't take it back.\"",
        truths: ("The tires were swapped at a used-tire lot two miles from {DL}'s home.", "A roadside shop did replace one flat."),
        defendant: [.direct("Did you swap the good tires for old ones?", "\"No. I did not swap anything. A roadside shop replaced a flat during the move, and I paid cash.\""), .direct("What happened to the tire that went flat?", "\"It blew out on the way. I called a roadside shop, and they put on a spare to get me going.\""), .direct("How far did you drive the truck?", "\"The move was long, but I did nothing to the tires myself. I only used the truck for the move.\""), .direct("Why did you rent the truck?", "\"To move my belongings to a new apartment. I had three loads from the old place and a short deadline.\""), .direct("What happened with the flat?", "\"On Saturday a rear tire blew on the highway. I called a mobile tire shop, and they came out and put on a spare.\""), .direct("Did you ask the shop to swap both rear tires?", "\"No. I asked them to fix the flat so I could keep moving. I never thought they replaced anything else.\""), .cross("Two rear tires were changed, and you say one flat explains it?", "\"I do not know about the second. I only know about one flat.\""), .cross("The tires turned up at a used-tire lot two miles from your home, didn't they?", "\"I heard that. I do not know how they got there.\""), .cross("The roadside shop gave you no receipt, did it?", "\"No. I paid cash and did not ask. I know that is not helpful.\""), .cross("You say only one tire changed. Who changed the second?", "\"I do not know. I did not touch the tires, and I did not check the second one.\""), .cross("Tires worn to the cords turned up at a used-tire lot near your home. Why?", "\"I heard that. I have no idea how they got there. I did not take anything to that lot.\"")],
        openings: ("A box truck went out on a Friday with six matching tires, signed off by the yard inspector. It came back Monday with two rear tires eight years older and worn to the cords, and {D} had rented it all weekend.", "The defense will present evidence that a roadside shop replaced a flat during the move, that {D} paid cash for it, and that {D} never swapped any good tires for bad ones."),
        closings: ("Six matching tires at pickup, two worn-to-the-cord tires at return, and $1,200 in replacements. Tires do not age eight years in a weekend.", "One flat, one spare, and a roadside worker who confirms it. The State must prove {D} swapped both tires, and the evidence shows only one tire changed."),
        timeline: [(-3, "Friday: the pickup photos show six matching tires."), (0, "Monday: the return inspection finds two worn rear tires."), (1, "The company prices the replacement pair."), (4, "The yard sends the photos and the invoice.")],
        identified: "The rental contract names {D}, and the yard's pickup photos show the original tires.",
        notDone: ["The roadside shop that fixed the flat was never identified or interviewed.", "The old tires were never traced to a used-tire lot."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let poolChemicalsV1 = SmallCases.make(
        key: "story.poolChemicals",
        category: .property,
        headlines: ["Garden Center's Pallet of Fertilizer Bags Loaded Into Trailer After Closing, Camera Shows Plate", "Receipt for One Bag Doesn't Cover Eighteen"],
        law: "misdLarceny",
        spec: "Stole fertilizer valued at $290 belonging to {V}, a garden center, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A garden center left a pallet of eighteen fertilizer bags outside after closing on {DATE}. A lot camera showed {D} back a trailer up to the pallet and load the bags. The garden center's receipt record showed {D} had bought one bag that afternoon. The eighteen bags were worth $290. {DL} says {D.he} thought the pallet was a free pile left for pickup.",
        state: [E(.video, 3, "Lot Camera", "{D} backs a trailer to the pallet and loads bags."), E(.document, 2, "Receipt", "{D} paid for one bag only."), E(.document, 2, "Inventory", "Eighteen bags missing, $290."), E(.statement, 1, "Manager", "The pallet was marked for return.")],
        defense: [E(.statement, 1, "Free Pile", "{DL} says {D.he} thought it was a free pile."), E(.statement, 1, "No Sign", "{DL} says nothing said it belonged to the store.")],
        role: "Garden center manager",
        exam: [.direct("What did you leave outside after closing?", "\"A pallet of eighteen fertilizer bags, marked for return. They were worth $290 together.\""), .direct("What does your lot camera show?", "\"{D} backing a trailer to the pallet and loading the bags. {D} had bought one bag that afternoon.\""), .direct("What did {D} ask a clerk that afternoon?", "\"What happened to returned pallets. That is what the clerk told me.\""), .direct("How did you stage the pallet outside that evening?", "\"A delivery came late, and we parked the pallet by the back fence with a return tag on a pallet wrap. We planned to take it back the next morning.\""), .direct("What did {D} do at the store that afternoon?", "\"{D} bought one bag of fertilizer at the register and asked the clerk what happens to returned pallets. The clerk said we send them back to the vendor.\""), .direct("What did the camera show after closing?", "\"At about 8:30, {D} pulled a trailer up to the fence and loaded eighteen bags in about ten minutes. {D} then drove off.\""), .cross("{D} says {D.he} thought the pallet was a free pile, doesn't {D.he}?", "\"That is what {D} says. But it was marked for return, and it was our property.\""), .cross("Was there a sign saying it was free?", "\"No. There was no such sign. The pallet was just sitting outside.\""), .cross("Did {D} hide what {D.he} was doing?", "\"No. {D} loaded in the open, on camera, with a trailer.\""), .cross("Was the pallet inside our fence line?", "\"It was just outside the fence but within our lot. A sign would have helped, and we did not have one.\""), .cross("Did {D} try to pay or leave a note?", "\"No. {D} left without paying or leaving any message.\"")],
        theory: ("{D} loaded a pallet of fertilizer and left.", "A customer who thought it was a free pile."),
        allocution: "\"I'm sorry. It won't happen again.\"",
        truths: ("{DL} backed a trailer to the pallet after closing.", "{DL} had asked a clerk that afternoon what happened to returned pallets."),
        defendant: [.direct("Did you take the eighteen bags?", "\"Yes, I loaded them. I thought the pallet was a free pile left for pickup after closing.\""), .direct("Why did you think they were free?", "\"I asked a clerk what happens to returned pallets, and I took the answer as a sign. I did not ask directly.\""), .direct("What were you doing at the garden center?", "\"Buying one bag of fertilizer for a small bed. While I was there, I asked about the pallet by the fence out of curiosity.\""), .direct("What did the clerk tell you?", "\"That returned pallets go back to the vendor. I did not hear that it was waiting for pickup that night.\""), .direct("Why did you come back after closing?", "\"I was driving by on my way to a job and saw the pallet by the road. I thought it had been left out for anyone to take.\""), .direct("What did you intend to do with the bags once you loaded them?", "\"I meant to use them on my yard and share some with neighbors. I assumed the pile was something the store was giving away.\""), .cross("You bought one bag that afternoon. Didn't that show you the price?", "\"I did. I saw a pile and I took it.\""), .cross("The pallet was marked for return, wasn't it?", "\"I did not see the mark. I should have looked more carefully.\""), .cross("You backed a trailer to it. Isn't that planned?", "\"I had a trailer already hooked up. It was convenient.\""), .cross("Did you look for a sign saying free?", "\"No. I did not see a sign, and I should have checked before loading.\""), .cross("If you believed it was free, why did you wait until after closing?", "\"Because I was off work then. I did not think about how it looked.\"")],
        openings: ("A garden center left eighteen fertilizer bags worth $290 on a pallet outside after closing, marked for return. A lot camera shows {D} backing a trailer to the pallet and loading the bags, after buying only one that day.", "The defense witnesses will explain that {D} honestly believed the pallet was a free pile left for pickup, and that {D} loaded in the open, on camera, with nothing to hide."),
        closings: ("A pallet marked for return, a trailer backed to it after closing, and one bag paid for out of eighteen. {D} took what was not free.", "A pallet at the curb, a trailer, and a customer who honestly thought it was free. The State must prove {D} knew it was not."),
        timeline: [(0, "3 p.m.: {D} buys one bag."), (0, "3:20 p.m.: {D} asks about returned pallets."), (0, "7:40 p.m.: the trailer arrives."), (0, "7:55 p.m.: the bags are loaded."), (1, "The manager finds the pallet gone.")],
        identified: "A lot camera.",
        mood: .divided,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let rentalBikeWreckV1 = SmallCases.make(
        key: "story.rentalBikeWreck",
        category: .property,
        headlines: ["Rental E-Bike Found at Foot of Boardwalk Stairs With Bent Wheel", "GPS Log Tracks Rental Bike to Wreck and Walk-Off"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a bike rental shop, causing damage of $890, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} rented an electric bike from a beach shop at 1 p.m. on {DATE}. The shop's GPS tracker shows the bike stopped moving at 2:20 p.m. at the bottom of a boardwalk stairway, where it was found with a bent front wheel and a cracked battery housing. {D} did not return the bike and ignored three calls from the shop. Repairs came to $890.",
        state: [E(.digital, 3, "GPS Log", "The tracker moves along the boardwalk for ninety minutes, then stops at the foot of the stairs at 2:20 p.m."), E(.physical, 2, "Bike", "A bent front wheel and a cracked battery housing; the seat is intact."), E(.document, 2, "Repair Estimate", "$890 for a wheel, fork and battery housing."), E(.statement, 2, "Shop Mechanic", "The brakes were checked at the morning start and passed.")],
        defense: [E(.statement, 1, "Brakes Failed", "{DL} says the brakes failed at the top of the stairs."), E(.document, 1, "Phone Log", "Three missed calls from the shop between 3 and 4 p.m. that {DL} did not answer.")],
        role: "Bike shop mechanic",
        exam: [.direct("What does your GPS log show?", "\"The bike moves along the boardwalk for ninety minutes and then stops at the foot of the stairs at 2:20 p.m.\""), .direct("What condition was the bike in when found?", "\"A bent front wheel and a cracked battery housing. The seat was intact.\""), .direct("What did the repairs cost?", "\"$890 for a wheel, a fork, and a battery housing. The estimate is in our file.\""), .direct("How are your rental bikes checked each day?", "\"Every morning we check brakes, tires, chain, and battery. I test both brakes and sign a tag on each bike before it goes out.\""), .direct("What did you find when the bike came back?", "\"It did not come back. The GPS led us to the foot of the boardwalk stairs where it was lying on its side with a bent wheel and a cracked battery housing.\""), .direct("What was the mileage and what did the tracker show?", "\"The bike traveled about eleven miles along the boardwalk in ninety minutes. It stopped at the stairs at 2:20 p.m. and did not move again.\""), .cross("Did you check the brakes at the start?", "\"Yes. I checked them at the morning start, and they passed.\""), .cross("A customer says the rear brake felt soft that week. Did you hear that?", "\"I did hear that about another bike. I do not recall a report on this one.\""), .cross("Did {D} return the bike?", "\"No. {D} did not return it and ignored three calls from the shop.\""), .cross("Could the brake cable have been frayed before the rental?", "\"I checked the brakes that morning and they passed. I cannot say what happened to the bike after it left the shop.\""), .cross("Did you inspect the brakes after the wreck?", "\"Yes, and I looked at the rear cable too. I cannot tell from looking when any wear on it happened.\"")],
        defenseRole: "Bike rental customer",
        defenseExam: [.direct("How were the brakes on your rental that week?", "\"Soft. I told the shop the rear brake felt loose, and nobody did anything about it before I went out.\""), .direct("Was yours the same bike as {D}'s?", "\"No, a different one. But the shop's bikes all sit together, and I think the cables on them were similar.\""), .direct("What did you see on the boardwalk that afternoon?", "\"A bike at the bottom of the stairs and a rider limping away from it. I did not see how it got there.\""), .direct("How do you know the shop's bikes?", "\"I rented one the same week. The shop has a line of bikes that all get a similar level of use and care.\""), .direct("What did you notice about your own rental?", "\"The rear brake felt spongy and I told the clerk on return. The clerk said they would look at it.\""), .direct("What did you do after you noticed your own rental felt wrong?", "\"I braked a few times at a stop and the rear lever was loose. I took it back to the shop and told the mechanic what I had felt.\""), .cross("Did you see the rider fall?", "\"No. I did not see the fall. I only saw the aftermath at the bottom of the stairs.\""), .cross("Could the bike have been ridden down the stairs on purpose?", "\"It is possible. I cannot say how it got there, and I did not see it happen.\""), .cross("How far were you from the stairs?", "\"About fifty feet. I saw the bike and the rider, but not the start.\""), .cross("Was your bike the one {D} rode?", "\"No. Mine was a different bike with a different number.\""), .cross("How can the brakes on your bike help us with {D}'s?", "\"They suggest a pattern in the fleet, but I cannot say what happened with {D}'s bike.\"")],
        theory: ("{D} rode the bike down stairs and left it.", "A brake failure caused a crash."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("The bike was ridden down the stairs on purpose.", "The rear brake cable had been frayed since the previous renter."),
        defendant: [.direct("Did you wreck the bike on purpose?", "\"No. The brakes failed, and I crashed down the stairs. It was an accident.\""), .direct("Why did you leave without returning it?", "\"I was hurt and embarrassed, and I did not know what to say. I limped away.\""), .direct("Did you answer the shop's calls?", "\"No. I ignored three. I was afraid and ashamed. I should have answered.\""), .direct("Why did you rent an electric bike?", "\"To ride the boardwalk with my family. I had not ridden one before and wanted to try it for the afternoon.\""), .direct("Walk us through what happened at the stairs.", "\"I came down the boardwalk and tried to stop at the top of the stairs. The rear brake barely held and the front took over, and I tumbled down.\""), .direct("How were you hurt?", "\"I scraped both knees and bruised a hip. A passerby helped me up, and I limped off feeling sick about the bike.\""), .cross("The shop says the brakes passed inspection that morning, doesn't it?", "\"They may have. The rear one felt loose to me from the start.\""), .cross("The GPS shows the bike was ridden for ninety minutes before the crash. Why not report the brake problem?", "\"I thought I could manage. I should have turned back.\""), .cross("The bike went down a stairway. How does that happen by accident?", "\"The brakes would not hold, and I could not stop. That is what happened.\""), .cross("The shop says it checked the brakes that morning. Why do you blame the brakes?", "\"Because they did not work when I needed them. I felt the rear brake go soft before I reached the stairs.\""), .cross("You rode for ninety minutes without a problem and ignored three calls afterward. Why?", "\"I was scared of getting charged for the damage. I should have called the shop right away.\"")],
        openings: ("An electric bike rented at 1 p.m. was found at 2:20 at the bottom of a boardwalk stairway, with a bent front wheel and a cracked battery housing. {D} never returned it and ignored three calls from the shop.", "Listen for the defense evidence, which will show that the rear brake was soft and loose, that another customer reported the same, and that {D} crashed by accident."),
        closings: ("A GPS log that ends at the foot of a stairway, a bent wheel, a cracked battery housing, and a renter who ignored every call. Repairs cost $890.", "A soft rear brake that a customer reported, a crash down a stairway, and an embarrassed rider. The State must prove {D} destroyed the bike on purpose."),
        timeline: [(0, "1:00 p.m.: {D} rents the e-bike."), (0, "2:20 p.m.: the tracker stops at the foot of the stairs."), (0, "3:00 p.m.: the shop starts calling."), (1, "The shop finds the bike and photographs the damage.")],
        identified: "The rental agreement and the tracker point to {D}.",
        notDone: ["No one tested the bike's brakes under load after the wreck.", "The mechanic's pre-rental checklist was never produced."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let rampLineFightV1 = SmallCases.make(
        key: "story.rampLineFight",
        category: .violent,
        headlines: ["Trailer Backed Slowly Down Ramp Ends in Punch at 5:15 a.m.", "Angler Left With Chipped Tooth After Wait for Boat Ramp"],
        law: "simpleAssault",
        spec: "Assaulted {V} by striking {V.him} in the face, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} was backing a boat trailer down a county ramp at 5:15 a.m. on {DATE} while a line of five trucks waited behind. {D}, third in line, walked up to the driver's window after ten minutes and punched {V} in the mouth through the open window. {V} chipped a front tooth. {D} says {V} had blocked the lane with an empty trailer for twenty minutes before launching.",
        state: [E(.video, 3, "Ramp Camera", "At 5:15 a.m. {D} walks to the cab of {V}'s truck and strikes {V} through the window."), E(.document, 2, "Dental Note", "A chipped front tooth and a split lip treated the same morning."), E(.statement, 2, "Next in Line", "The driver behind {D} saw the punch and says {V} said nothing first.")],
        defense: [E(.statement, 1, "Lane Blocked", "{DL} says {V} sat with an empty trailer in the lane for twenty minutes."), E(.statement, 1, "Shove", "{DL} says {V} shoved {D.him} when {D.he} knocked on the window.")],
        role: "Ramp attendant",
        exam: [.direct("What happened at the ramp at 5:15 a.m.?", "\"{V} was backing a boat trailer down the ramp with five trucks waiting. {D}, third in line, walked up to {V}'s window and punched {V} in the mouth.\""), .direct("What does the ramp camera show?", "\"{D} walking to the cab of {V}'s truck and striking {V} through the window. It is clear.\""), .direct("What injury did {V} have?", "\"A chipped front tooth and a split lip, treated that morning. A dental note records it.\""), .direct("What was the ramp like at 5:15 that morning?", "\"Dark, with a few lights along the lane. Five trucks with trailers waited in line while a truck backed a boat trailer toward the water.\""), .direct("How long had {V} been working on the trailer?", "\"About twenty minutes, from what I saw. {V} backed slowly and stopped twice to adjust. The line was not moving.\""), .direct("What did {D} do?", "\"{D} walked up to {V}'s truck, knocked on the window, and then swung a fist through it. The blow landed on {V}'s mouth.\""), .cross("{D} says {V} blocked the lane for twenty minutes, doesn't {D.he}?", "\"I know that is what {D} says. The trailer did sit in the lane for a while.\""), .cross("Did {V} shove {D} first?", "\"I was told {V} shoved {D}'s shoulder first. I did not see that part.\""), .cross("Did {V} say anything to {D}?", "\"The driver behind {D} says {V} said nothing before the swing.\""), .cross("Did {V} do or say anything to provoke it?", "\"I did not see a provocation. I saw {V} turn toward the window and then get hit.\""), .cross("Was there any pushing before the punch?", "\"I did not see it. I was behind my booth. A driver behind {D} told me later that there may have been.\"")],
        defenseRole: "Fellow angler in line",
        defenseExam: [.direct("How long had the trailer sat in the lane?", "\"Close to twenty minutes, with the truck just idling. We were all waiting behind it and getting frustrated.\""), .direct("What did you see at the cab?", "\"{D} knocked on the window, and {V} shoved {D}'s shoulder. Then {D} threw a punch through the window.\""), .direct("Did you see {D} throw the punch?", "\"Yes. I saw it clearly from three trucks back. It happened quickly.\""), .direct("How long have you fished from this ramp?", "\"Fifteen years. I know the early morning crowd and the routine for launching.\""), .direct("What did {V} do in the lane?", "\"Idled with an empty trailer for the better part of twenty minutes. A few of us honked, and {V} just sat there.\""), .direct("What happened when {D} reached the cab?", "\"{D} knocked, and {V} reached out and shoved {D}'s shoulder. Then {D} hit back.\""), .cross("Did {V} say anything before the shove?", "\"I did not hear. I was too far away to hear the words.\""), .cross("Do you know {D} from before?", "\"We fish the same ramp. I know {D} a little, and I am not going to pretend otherwise.\""), .cross("Could you hear what was said?", "\"No. I was three trucks back and the engines were loud.\""), .cross("Do you think the punch was justified?", "\"I would not say that. It was a punch, and it chipped a tooth.\""), .cross("You were behind {D} in line and could not see {V}'s hands, could you?", "\"Not clearly. I saw {V}'s arm on the window frame and nothing else. I did not see what happened in the cab until after the punch.\"")],
        theory: ("{D} punched {V} over a slow launch.", "{V} blocked the ramp and shoved first."),
